// TypeScript Version: 4.1

/**
* Evaluates the factorial of `n` as a single-precision floating-point number.
*
* ## Notes
*
* -   If `n` is greater than `34` and an integer, the function returns `+Infinity`, as larger factorial values overflow single-precision floating-point format.
* -   For non-integer inputs, the function returns $\Gamma(n+1)$, where $\Gamma$ is the Gamma function.
* -   The factorial of a negative integer is not defined and results in `NaN`.
*
* @param x - input value
* @returns factorial
*
* @example
* var v = factorialf( 3.0 );
* // returns 6.0
*
* @example
* var v = factorialf( -1.5 );
* // returns ~-3.545
*
* @example
* var v = factorialf( -0.5 );
* // returns ~1.772
*
* @example
* var v = factorialf( 0.5 );
* // returns ~0.886
*
* @example
* var v = factorialf( -10.0 );
* // returns NaN
*
* @example
* var v = factorialf( 35.0 );
* // returns Infinity
*
* @example
* var v = factorialf( NaN );
* // returns NaN
*/
declare function factorialf( x: number ): number;


// EXPORTS //

export = factorialf;
